// Map ransomware.live sector labels to MTS-OPS valid sectors
const SECTOR_MAP = {
  'Shipping': 'Maritime',
  'Maritime': 'Maritime',
  'Transportation': 'Transportation',
  'Energy': 'Energy',
  'Water': 'Water',
  'Healthcare': 'Healthcare',
  'Financial': 'Financial',
  'Finance': 'Financial',
  'Telecom': 'Telecom',
  'Government': 'Government',
  'Manufacturing': 'Manufacturing',
};

// Known threat groups — anything else becomes 'Unknown'
const KNOWN_GROUPS = ['LockBit3', 'Akira', 'BlackCat', 'Cl0p', 'Play'];

function normalizeGroup(raw) {
  if (!raw) return 'Unknown';
  const clean = raw.toLowerCase().replace(/[\s\-_\.]/g, '');
  const match = KNOWN_GROUPS.find(g => g.toLowerCase().replace(/[\s\-_\.]/g, '') === clean);
  return match || 'Unknown';
}

function normalizeSector(raw) {
  if (!raw) return 'Manufacturing';
  return SECTOR_MAP[raw] || 'Manufacturing';
}

// Input is the full response body — ransomware.live returns a JSON array
const victims = Array.isArray($input.first().json) ? $input.first().json : [];

// Only ingest victims discovered in the last 24 hours to avoid re-ingesting stale data.
// The source_url unique index in Supabase is the final safety net.
const cutoffMs = Date.now() - 24 * 60 * 60 * 1000;

const items = victims
  .filter(v => {
    if (!v.discovered) return false;
    return new Date(v.discovered).getTime() >= cutoffMs;
  })
  .map(v => {
    const org = v.post_title || v.website || 'Unknown organization';
    const sourceUrl = `https://www.ransomware.live/victim/${encodeURIComponent(org)}-${v.group_name || 'unknown'}`;

    return {
      json: {
        type: 'incident',
        data: {
          title: `Ransomware: ${org}`.slice(0, 200),
          severity: 'High',
          sector: normalizeSector(v.activity),
          attack_vector: 'Ransomware',
          target_organization: org.slice(0, 200),
          target_country: v.country || null,
          threat_group: normalizeGroup(v.group_name),
          description: v.description ? v.description.slice(0, 500) : null,
          source_url: sourceUrl,
          iocs: {}
        }
      }
    };
  });

if (items.length === 0) {
  // Return a no-op item so the workflow doesn't error on empty output
  return [{ json: { __skip: true } }];
}

return items;
